18	// ScannerHelper is a helper to scan new line delimited records from io.Reader and determine when to flush.
19	// It uses new line delimiters and bytes for batching.
20	// Not safe for concurrent use.
21	type ScannerHelper struct {
22		batchHelper *BatchHelper
23		bufReader   *bufio.Reader
24		offset      int64
25	}
26	
27	// NewScannerHelper creates a new ScannerHelper that reads from the provided io.Reader.
28	// It accepts optional encoding.DecoderOption to configure batch flushing behavior.
29	// If a bufio.Reader is provided, it will be used as-is. Otherwise, one will be derived with default buffer size.
30	func NewScannerHelper(reader io.Reader, opts ...encoding.DecoderOption) (*ScannerHelper, error) {
31		batchHelper := NewBatchHelper(opts...)
32	
33		var bufReader *bufio.Reader
34		if br, ok := reader.(*bufio.Reader); ok {
35			bufReader = br
36		} else {
37			bufReader = bufio.NewReader(reader)
38		}
39	
40		if batchHelper.options.Offset != 0 {
41			_, err := bufReader.Discard(int(batchHelper.options.Offset))
42			if err != nil {
43				return nil, fmt.Errorf("failed to discard offset %d: %w", batchHelper.options.Offset, err)
44			}
45		}
46	
47		return &ScannerHelper{
48			batchHelper: batchHelper,
49			bufReader:   bufReader,
50			offset:      batchHelper.options.Offset,
51		}, nil
52	}
53	
54	// ScanString scans the next line from the stream and returns it as a string. This excludes new line delimiter.
55	// flush indicates whether the batch should be flushed after processing this string.
56	// err is non-nil if an error occurred during scanning. If the end of the stream is reached, err will be io.EOF.
57	func (h *ScannerHelper) ScanString() (line string, flush bool, err error) {
58		internal, b, err := h.scanInternal()
59		return string(internal), b, err
60	}
61	
62	// ScanBytes scans the next line from the stream and returns it as a byte slice. This excludes new line delimiter.
63	// flush indicates whether the batch should be flushed after processing these bytes.
64	// err is non-nil if an error occurred during scanning. If the end of the stream is reached, err will be io.EOF.
65	func (h *ScannerHelper) ScanBytes() (bytes []byte, flush bool, err error) {
66		b, flush, err := h.scanInternal()
67		if b != nil {
68			cpy := make([]byte, len(b))
69			copy(cpy, b)
70			return cpy, flush, err
71		}
72		return nil, flush, err
73	}
74	
75	func (h *ScannerHelper) scanInternal() ([]byte, bool, error) {
76		var isEOF bool
77		b, err := h.bufReader.ReadBytes('\n')
78		if err != nil {
79			if err != io.EOF {
80				return nil, false, err
81			}
82			isEOF = true
83		}
84	
85		if len(b) == 0 && isEOF {
86			return nil, true, io.EOF
87		}
88	
89		h.offset += int64(len(b))
90		h.batchHelper.IncrementBytes(int64(len(b)))
91		h.batchHelper.IncrementItems(1)
92	
93		var flush bool
94		if h.batchHelper.ShouldFlush() {
95			h.batchHelper.Reset()
96			flush = true
97		}
98	
99		b = bytes.TrimSpace(b)
100	
101		if isEOF {
102			return b, flush, io.EOF
103		}
104	
105		return b, flush, nil
106	}
107	
108	// Offset returns the current byte offset read from the stream.
109	func (h *ScannerHelper) Offset() int64 {
110		return h.offset
111	}
112	
113	// Options returns the DecoderOptions used by the ScannerHelper's BatchHelper.
114	func (h *ScannerHelper) Options() encoding.DecoderOptions {
115		return h.batchHelper.Options()
116	}
