// NewLogsDecoder returns a streaming LogsDecoder that detects the CloudTrail log
// format and processes records incrementally.
//
// For the S3 Records format (top-level "Records" array), the offset is a record
// count: WithOffset(n) skips the first n records before decoding, each batch
// contains up to FlushItems records, and Offset returns the number of records
// processed so far.
//
// For the CloudWatch subscription filter and digest formats, the whole payload
// is decoded as a single batch and the offset reflects the number of bytes
// consumed. A non-zero starting offset means the payload has already been
// consumed, so the first DecodeLogs call returns io.EOF immediately while Offset
// still reports the total byte length of the input.
func (u *CloudTrailLogUnmarshaler) NewLogsDecoder(reader io.Reader, options ...encoding.DecoderOption) (encoding.LogsDecoder, error) {
	bufferedReader := bufio.NewReaderSize(reader, readerBufferSize)

	// Peek into the first 64 bytes to determine the type of CloudTrail log
	peekBytes, err := bufferedReader.Peek(64)
	if err != nil && !errors.Is(err, io.EOF) {
		return nil, fmt.Errorf("failed to peek into CloudTrail log: %w", err)
	}

	firstKey, err := extractFirstKey(peekBytes)
	if err != nil {
		return nil, fmt.Errorf("failed to extract the first JSON key: %w", err)
	}

	batchHelper := xstreamencoding.NewBatchHelper(options...)
	decoder := gojson.NewDecoder(bufferedReader)

	// Check for S3 CloudTrail log format (most common)
	if firstKey == "Records" {
		return u.newS3Decoder(decoder, batchHelper)
	}

	// Check for CloudWatch subscription filter format
	if isCloudWatchKey(firstKey) {
		return u.newSingleBatchDecoder(decoder, batchHelper.Options().Offset, u.decodeCloudWatch), nil
	}

	// Otherwise, assume it's a CloudTrail digest record
	return u.newSingleBatchDecoder(decoder, batchHelper.Options().Offset, u.decodeDigest), nil
}

// newS3Decoder returns a LogsDecoder for the S3 Records CloudTrail format.
// The offset tracks the number of records processed; WithOffset skips that many
// records before decoding begins.
func (u *CloudTrailLogUnmarshaler) newS3Decoder(decoder *gojson.Decoder, batchHelper *xstreamencoding.BatchHelper) (encoding.LogsDecoder, error) {
	// Check opening bracket
	if token, err := decoder.Token(); err != nil || token != gojson.Delim('{') {
		return nil, fmt.Errorf("expected '{': %w", err)
	}

	// Move to Records array
	if _, err := decoder.Token(); err != nil {
		return nil, fmt.Errorf("expected 'Records' key: %w", err)
	}

	// Check for array opening
	if token, err := decoder.Token(); err != nil || token != gojson.Delim('[') {
		return nil, fmt.Errorf("expected '[': %w", err)
	}

	var recordCount int64

	// Skip the first records.Offset records so decoding resumes at the offset.
	for recordCount < batchHelper.Options().Offset {
		if !decoder.More() {
			break
		}
		var raw gojson.RawMessage
		if err := decoder.Decode(&raw); err != nil {
			return nil, err
		}
		recordCount++
	}

	decodeFunc := func() (plog.Logs, error) {
		if !decoder.More() {
			return plog.Logs{}, io.EOF
		}

		logs, resourceLogs, scopeLogs := u.createLogs()
		logRecords := scopeLogs.LogRecords()

		init := true
		for decoder.More() {
			record := CloudTrailRecord{}
			if err := decoder.Decode(&record); err != nil {
				return plog.Logs{}, err
			}

			recordCount++
			batchHelper.IncrementItems(1)

			if init {
				u.setResourceAttributes(resourceLogs.Resource().Attributes(), record)
				init = false
			}

			logRecord := logRecords.AppendEmpty()
			if err := u.setLogRecord(logRecord, &record); err != nil {
				return plog.Logs{}, err
			}

			if batchHelper.ShouldFlush() {
				batchHelper.Reset()
				return logs, nil
			}
		}

		return logs, nil
	}

	return xstreamencoding.NewLogsDecoderAdapter(decodeFunc, func() int64 { return recordCount }), nil
}

// newSingleBatchDecoder returns a LogsDecoder for formats that are decoded as a
// single batch (CloudWatch subscription filter and digest). The offset reflects
// the number of bytes consumed. A non-zero starting offset indicates the payload
// has already been consumed, so the first DecodeLogs returns io.EOF while the
// offset still reports the total byte length of the input.
func (u *CloudTrailLogUnmarshaler) newSingleBatchDecoder(
